  font-weight: bold;
  line-height: 24px;
}

p {
  margin-top: 0;
  margin-bottom: 0;
  line-height: 150%;
}

a {
  margin-right: auto;
  text-decoration: none;
  transition: all .3s;
  position: static;
}

ul {
  margin-top: 20px;
  margin-bottom: 20px;
  margin-left: 20px;
  padding-left: 20px;
  list-style-type: disc;
}

ol {
  margin-top: 0;
  margin-bottom: 10px;
  padding-left: 40px;
  font-size: 16px;
  line-height: 20%;
}

li {
  color: #525c6b;
  letter-spacing: -.5px;
  margin-bottom: 20px;
  padding-left: 15px;
  font-size: 16px;
  font-weight: 300;
  line-height: 150%;
}

img {
  display: inline-block;
}

label {
  letter-spacing: -.5px;
  margin-bottom: 10px;
  font-size: 19px;
  font-weight: 700;
  line-height: 19px;
  display: block;
}

strong {
  font-weight: 700;
}

blockquote {
  text-align: left;
  letter-spacing: -.5px;
  background-image: url('../images/quotes-1.svg');
  background-position: 0 0;
  background-repeat: no-repeat;
  background-size: 30px;
  border-left: 0 #000;
  width: 70%;
  margin: 60px auto 80px 0;
  padding: 0 0 0 64px;
  font-size: 20px;
  font-style: normal;
  font-weight: 600;
  line-height: 1.3em;
  display: block;
}

figure {
  width: 100%;
  margin-bottom: 10px;
}

figcaption {
  color: #525c6b;
  text-align: left;
  margin-top: 5px;
  font-style: italic;
  font-weight: 300;
}

.image {
  margin-bottom: 10px;
}

.image.webinar {
  margin-bottom: 0;
}

.image.webinar.arrow_review {
  position: absolute;
  inset: 1% auto auto -10%;
}

.image.webinar.review {
  border-radius: 100px;
  box-shadow: 1px 1px 24px #454e5c26;
}

.image.bullet {
  margin-bottom: 35px;
}

.image.social {
  margin-bottom: 0;
}

._20 {
  font-size: 20px;
}

.image-2 {
