}

.caps {
  letter-spacing: 3px;
  text-transform: uppercase;
  margin-bottom: 20px;
  font-size: 12px;
}

.link {
  color: #ff3108;
  font-style: normal;
  text-decoration: none;
  transition: all .2s;
}

.link.light {
  color: var(--phoenix-red);
  font-size: 12px;
  font-weight: 300;
}

.link.green {
  color: #79ffca;
}

.link.white:hover {
